 public void Close(bool keep=true){if(!IsOpen)return;var runner=GetComponent<RoadMapTrialSession>();if(runner&&runner.Busy){notice="시험 창을 종료한 뒤 편집기를 닫으세요";confirmClose=false;return;}if(!keep){document=null;history=null;}IsOpen=false;confirmClose=false;closedFrame=Time.frameCount;session.paused=previousPause;Time.timeScale=previousScale;if(preview)preview.Clear();}
