 public bool Save(){try{RoadMapStore.Save(FilePath,document);saved=JsonUtility.ToJson(document);notice="수정본 저장 완료 · 기본 지도 지정은 별도";return true;}catch(Exception e){notice="저장 실패: "+e.Message;return false;}}
