 public bool Trial(){Check();if(issues.Any(i=>i.error))return false;try{var runner=GetComponent<RoadMapTrialSession>();if(!runner)runner=gameObject.AddComponent<RoadMapTrialSession>();runner.editor=this;runner.Launch(document,TrialStart,TrialGoal);notice="별도 시험 창 실행 중 · 원래 영업은 정지";return true;}catch(Exception e){notice="시험 실행 실패: "+e.Message;return false;}}
