 void Left(){GUI.Label(new Rect(18,90,230,25),"교차로ID / 차로 검색",label);search=GUI.TextField(new Rect(18,120,230,29),search,field);leftScroll=GUI.BeginScrollView(new Rect(18,157,230,425),leftScroll,new Rect(0,0,210,Mathf.Max(400,session.world.map.junctionRules.Length*32+document.lanes.Count(l=>l.ruleId==junction)*32+70)));float y=0;GUI.Label(new Rect(0,y,210,25),junction+" · 차로 목록",label);y+=28;foreach(var l in document.lanes.Where(l=>l.ruleId==junction&&(string.IsNullOrEmpty(search)||l.id.Contains(search)||junction.Contains(search))).OrderBy(l=>l.number)){if(Button(0,y,205,(l.disabled?"× ":l.number+"차로 ")+Short(l.id)))Select(l.id);y+=32;}GUI.Label(new Rect(0,y,210,25),"다른 교차로",label);y+=28;foreach(var r in session.world.map.junctionRules.Where(r=>string.IsNullOrEmpty(search)||r.id.IndexOf(search,StringComparison.OrdinalIgnoreCase)>=0)){if(Button(0,y,205,(junction==r.id?"● ":"")+r.id))Focus(r.id);y+=32;}GUI.EndScrollView();
